// Settings -> object (client concierge bot, AI-guarded defaults).
// The Telegram bot secret is no longer read from Settings at all: transport runs entirely through n8n Credentials.
const rows = $input.all().map(i => i.json);
const settings = {};
for (const r of rows) {
  const key = (r.key ?? r.Key ?? '').toString().trim();
  if (!key) continue;
  settings[key] = (r.value ?? r.Value ?? '').toString().trim();
}
function bool(v, def){ if (v === undefined || v === '') return def; return String(v).toLowerCase() === 'true' || v === '1'; }
function num(v, def){ const n = Number(v); return Number.isFinite(n) ? n : def; }
const cfg = {
  owner_chat_id: settings.owner_chat_id || '551662084',
  timezone: settings.timezone || 'Europe/Chisinau',
  lead_intake_webhook_url: settings.lead_intake_webhook_url || 'https://ghennadi.app.n8n.cloud/webhook/finmentor-lead-intake',
  website_url: settings.website_url || 'https://finmentor.md',
  default_language: (settings.default_language || 'ru').toLowerCase(),
  bot_enabled: bool(settings.bot_enabled, true),
  client_ai_enabled: bool(settings.client_ai_enabled, false),
  client_ai_model: settings.client_ai_model || 'PASTE_AI_MODEL_PLACEHOLDER_HERE',
  client_ai_temperature: num(settings.client_ai_temperature, 0.2)
};
return [{ json: { settings: cfg } }];

// Parse Telegram Update (client bot). Trigger отдаёт update на верхнем уровне (или в .body).
const u = $('Telegram Client Trigger').first().json;
const update = u.body || u;
const cb = update.callback_query || null;
const msg = update.message || update.edited_message || null;

let chat_id='', user_id='', username='', first_name='', last_name='', language='', message_text='', callback_data='', callback_query_id='';
if (cb) {
  chat_id = String(cb.message && cb.message.chat ? cb.message.chat.id : '');
  user_id = String(cb.from ? cb.from.id : '');
  username = (cb.from && cb.from.username) || '';
  first_name = (cb.from && cb.from.first_name) || '';
  last_name = (cb.from && cb.from.last_name) || '';
  language = (cb.from && cb.from.language_code) || '';
  callback_data = cb.data || '';
  callback_query_id = cb.id || '';
} else if (msg) {
  chat_id = String(msg.chat ? msg.chat.id : '');
  user_id = String(msg.from ? msg.from.id : '');
  username = (msg.from && msg.from.username) || '';
  first_name = (msg.from && msg.from.first_name) || '';
  last_name = (msg.from && msg.from.last_name) || '';
  language = (msg.from && msg.from.language_code) || '';
  message_text = msg.text || '';
}
if (!chat_id) return [];  // служебный апдейт без чата — игнор
return [{ json: {
  chat_id, user_id, username, first_name, last_name, language,
  message_text, callback_data, callback_query_id,
  is_callback: !!cb,
  raw_update: JSON.stringify(update).slice(0, 4000)
}}];

// Bot_Events row for the delivered, non-lead branch.
const b = $('Build Bot Response').first().json;
const p = $('Parse Telegram Update').first().json;
const d = b.debug || {};
const ev = b.event || {};
let transport = {};
try { transport = $('Send Client Message').first().json || {}; } catch (e) { transport = {}; }
let saved = {};
try { saved = $('Save Bot Session').first().json || {}; } catch (e) { saved = {}; }
const sessionSaveFailed = !!(saved.error || saved.errorMessage);
return [{ json: {
  event_id: `${p.chat_id}-${Date.now()}`,
  ts: new Date().toISOString(),
  chat_id: String(p.chat_id || ''),
  user_id: String(p.user_id || ''),
  username: String(p.username || ''),
  event_type: p.is_callback ? 'callback_received' : 'message_received',
  state_before: String(d.state_before || ''),
  state_after: String(d.state_after || ''),
  message_text: String(p.message_text || '').slice(0, 500),
  callback_data: String(p.callback_data || ''),
  detail: sessionSaveFailed ? 'session_save_failed' : ('message_delivered: ' + (ev.detail || '')),
  raw_json: JSON.stringify({ correlation_id: transport.correlation_id || '', message_id: transport.message_id || '', debug: d, session_notes: (b.session && b.session.notes) || '' }).slice(0, 4000)
} }];

// Bot_Events row for the lead branch: separates 'Intake accepted the lead' from 'client confirmation delivered'.
const p = $('Parse Telegram Update').first().json;
const b = $('Build Bot Response').first().json;
let intake = null;
try { intake = $('Parse Intake Response').first().json; } catch (e) { intake = null; }
let transport = {};
try { transport = $('Send Intake Confirmation').first().json || {}; } catch (e) { transport = {}; }
const persisted = $('Get Bot Session').first().json || {};
const retryPath = intake === null;
const intakeOk = retryPath ? String(persisted.lead_id || '') !== '' : intake.intake_ok === true;
const delivered = transport.ok === true;
let detail;
if (retryPath) detail = delivered ? 'lead_confirmation_delivered (retry, no second intake call)' : 'lead_confirmation_failed (retry)';
else if (!intakeOk) detail = 'lead_intake_failed: ' + String(intake.error_code || '');
else detail = delivered ? 'lead_intake_ok + lead_confirmation_delivered' : 'lead_intake_ok + lead_confirmation_failed';
return [{ json: {
  event_id: `${p.chat_id}-lead-${Date.now()}`,
  ts: new Date().toISOString(),
  chat_id: String(p.chat_id || ''),
  user_id: String(p.user_id || ''),
  username: String(p.username || ''),
  event_type: retryPath ? 'lead_confirmation_retry' : (intakeOk ? 'lead_intake_ok' : 'lead_intake_failed'),
  state_before: String((b.debug || {}).state_before || ''),
  state_after: String((b.debug || {}).state_after || ''),
  message_text: String(p.message_text || '').slice(0, 500),
  callback_data: String(p.callback_data || ''),
  detail,
  raw_json: JSON.stringify({ lead_id: (intake && intake.lead_id) || persisted.lead_id || '', mode: (intake && intake.mode) || '', priority: (intake && intake.priority) || '', financial_zone: (intake && intake.financial_zone) || '', confirmation: { ok: delivered, error_code: transport.error_code || '', correlation_id: transport.correlation_id || '' } }).slice(0, 4000)
} }];

// Reached only after Transport confirmed ok === true, so the PROPOSED session becomes the PERSISTED session here.
// Cycle fields are re-attached from the cycle gate, because the state machine's baseSession() does not carry them.
// lead_id is taken from the cycle gate (confirmed only) and NEVER from the state machine's provisional TG-* id.
const b = $('Build Bot Response').first().json;
const g = $('Get Bot Session').first().json || {};
const s = Object.assign({}, b.session || {});
const now = new Date().toISOString();
const str = v => String(v == null ? '' : v).trim();
s.cycle_id = str(g.cycle_id);
s.previous_lead_id = str(g.previous_lead_id);
s.lead_id = str(g.lead_id);
s.lead_cycle_id = str(g.lead_cycle_id);
s.lead_sent_at = str(g.lead_sent_at);
s.lead_intake_ok = str(g.lead_intake_ok);
// P7.2 — the key rides with the cycle fields for the same reason they are here: the state
// machine's baseSession() does not carry it, so it must come from the gate that decided it.
// F7: when this turn minted, the value written is the one the READBACK VERIFIED.
let verifiedKey72 = '';
try {
  const v72 = $('Issuance Verdict').first().json || {};
  if (v72.__advance === true) { verifiedKey72 = String(v72.__verified_submission_key || ''); }
} catch (e) { verifiedKey72 = ''; }
s.submission_key = verifiedKey72 || str(g.submission_key);
const decision = str(s.consent);
if (decision === 'yes' || decision === 'no') {
  const alreadyStamped = str(g.consent) !== '' && str(g.consent_cycle_id) === str(g.cycle_id);
  s.consent_cycle_id = alreadyStamped ? str(g.consent_cycle_id) : str(g.cycle_id);
  s.consent_at = alreadyStamped ? (str(g.consent_at) || now) : now;
} else {
  s.consent_cycle_id = ''; s.consent_at = '';
}
const COLS = ['session_id','chat_id','user_id','username','first_name','last_name','language','state','created_at','updated_at','last_message_at','entry_source','selected_service','business_model','turnover_range','main_pain','urgency','has_cfo','documents_status','contact_phone','contact_email','contact_name','company','free_text_request','consent','lead_id','lead_sent_at','status','notes','raw_json','cycle_id','consent_cycle_id','consent_at','lead_cycle_id','lead_intake_ok','previous_lead_id','submission_key'];
const row = {};
for (const c of COLS) row[c] = (s[c] === undefined || s[c] === null) ? '' : String(s[c]).slice(0, 45000);
return [{ json: row }];

// Presentation contract for FINMENTOR Telegram Client Transport.
// The state machine already emits reply_markup.inline_keyboard, so the layout id is derived from the ACTUAL
// keyboard shape + per-position button type. Nothing inside the state machine is modified.
// Approved UX note: a [U],[C] keyboard (bot_disabled screen) is normalised to [C],[U] = L2_CU.
// An unknown signature is NEVER silently downgraded to L0_NONE: it is routed to the controlled recovery branch.
// L0_NONE is reserved for screens that genuinely have no keyboard by design (empty signature).
const b = $('Build Bot Response').first().json;
const p = $('Parse Telegram Update').first().json;
const body = b.tg_body || {};
let rows = (body.reply_markup && Array.isArray(body.reply_markup.inline_keyboard)) ? body.reply_markup.inline_keyboard : [];

function typeOf(btn) { if (btn && typeof btn.url === 'string' && btn.url.trim() !== '') return 'U'; return 'C'; }
function sig(rws) { return rws.map(r => (r || []).map(typeOf).join('')).join('|'); }

let signature = sig(rows);
if (signature === 'U|C') { rows = [rows[1], rows[0]]; signature = 'C|U'; }

const MAP = {
  '': 'L0_NONE',
  'C': 'L1_C',
  'C|C': 'L2_C',
  'C|U': 'L2_CU',
  'C|C|C': 'L3_C',
  'C|C|U': 'L3_CCU',
  'C|C|C|C': 'L4_CCCC',
  'C|C|U|C': 'L4_CCUC',
  'C|C|C|U|C': 'L5_CCCUC',
  'C|C|C|C|C|C': 'L6_C',
  'C|C|C|C|C|C|C': 'L7_C',
  'C|C|C|C|C|C|C|C': 'L8_C',
  'C|C|C|C|UC': 'LAYOUT_MENU',
  'CC|C|CC|CC|C': 'LAYOUT_BMODEL'
};

const layout = MAP[signature] || '';
const mapped = layout !== '';

const kbRows = rows.map(r => (r || []).map(btn => {
  const o = { text: String((btn && btn.text) || '') };
  if (typeOf(btn) === 'U') o.url = String(btn.url); else o.callback_data = String((btn && btn.callback_data) || '');
  return o;
}));

// Stable Telegram identity, not a random id: needed for duplicate protection and tracing.
const corr = p.is_callback ? ('cb:' + String(p.callback_query_id || '')) : ('msg:' + String(p.chat_id || '') + ':' + String(p.message_text || '').slice(0, 24));

return [{ json: {
  chat_id: String(body.chat_id || b.chat_id || ''),
  text: String(body.text || ''),
  keyboard_layout_id: layout,
  keyboard_data: { rows: kbRows },
  parse_mode: '',
  disable_preview: true,
  correlation_id: corr.slice(0, 100),
  layout_mapped: mapped,
  keyboard_signature: signature
} }];

// Delivery failed: the PROPOSED session is deliberately NOT persisted, so Bot_Sessions keeps the previous state.
const b = $('Build Bot Response').first().json;
const p = $('Parse Telegram Update').first().json;
const t = $input.first().json || {};
const d = b.debug || {};
let unmapped = '';
try { unmapped = $('Build Transport Request').first().json.layout_unmapped || ''; } catch (e) { unmapped = ''; }
return [{ json: {
  event_id: `${p.chat_id}-${Date.now()}`,
  ts: new Date().toISOString(),
  chat_id: String(p.chat_id || ''),
  user_id: String(p.user_id || ''),
  username: String(p.username || ''),
  event_type: p.is_callback ? 'callback_received' : 'message_received',
  state_before: String(d.state_before || ''),
  state_after: String(d.state_before || ''),
  message_text: String(p.message_text || '').slice(0, 500),
  callback_data: String(p.callback_data || ''),
  detail: 'message_delivery_failed: ' + String(t.error_code || 'UNKNOWN') + (t.retryable ? ' (retryable)' : ''),
  raw_json: JSON.stringify({ correlation_id: t.correlation_id || '', error_code: t.error_code || '', retryable: t.retryable === true, proposed_state_discarded: d.state_after || '', layout_unmapped: unmapped }).slice(0, 4000)
} }];

// Lead Intake success is defined ONLY by the business contract ok === true.
// HTTP 2xx, a parseable body, or the absence of an exception are NOT success.
// The state machine pre-generates a provisional lead_id; it is never persisted unless Intake confirmed the lead.
// A confirmed lead is stamped with the current cycle_id so that it protects retries within this cycle only.
const r = $input.first().json || {};
const body = (r.body && typeof r.body === 'object') ? r.body : r;
const ok = body.ok === true || String(body.ok).toLowerCase() === 'true';
const b = $('Build Bot Response').first().json;
const g = $('Get Bot Session').first().json || {};
const proposed = Object.assign({}, b.session || {});
const now = new Date().toISOString();
const str = v => String(v == null ? '' : v).trim();
const confirmedLeadId = str(body.lead_id);
function note(s, flag) { const parts = String(s || '').split(';').map(x => x.trim()).filter(Boolean); if (!parts.includes(flag)) parts.push(flag); return parts.join('; ').slice(0, 500); }
proposed.updated_at = now;
proposed.last_message_at = now;
proposed.cycle_id = str(g.cycle_id);
proposed.previous_lead_id = str(g.previous_lead_id);
proposed.consent_cycle_id = str(g.consent_cycle_id) || str(g.cycle_id);
proposed.consent_at = str(g.consent_at) || now;
if (ok) {
  proposed.lead_id = confirmedLeadId || str(g.lead_id);
  proposed.lead_cycle_id = str(g.cycle_id);
  proposed.lead_intake_ok = 'true';
  proposed.lead_sent_at = now;
  proposed.status = 'lead_sent';
  proposed.notes = note(proposed.notes, 'lead_intake_ok');
} else {
  proposed.lead_id = str(g.lead_id);
  proposed.lead_cycle_id = str(g.lead_cycle_id);
  proposed.lead_intake_ok = str(g.lead_intake_ok);
  proposed.lead_sent_at = str(g.lead_sent_at);
  proposed.status = 'lead_pending';
  proposed.notes = note(proposed.notes, 'intake_failed_review_needed');
}
return [{ json: {
  intake_ok: ok,
  lead_id: ok ? (confirmedLeadId || str(g.lead_id)) : '',
  cycle_id: str(g.cycle_id),
  mode: String(body.mode || ''),
  priority: String(body.priority || ''),
  financial_zone: String(body.financial_zone || ''),
  error_code: ok ? '' : String(body.error_code || 'INTAKE_NOT_OK'),
  retryable: body.retryable === true,
  session: proposed
} }];

// Persist the Intake outcome BEFORE the client confirmation is attempted:
// the lead may already exist in Pipeline, and that fact must survive a failed confirmation.
const s = Object.assign({}, $input.first().json.session || {});
// P7.2 — Parse Intake Response builds its session from the state machine, which has no key.
// Re-attached FROM THE CYCLE GATE, exactly like the cycle fields, and for the same reason: the
// value is decided in one place and every writer reads it from there.
let g72 = {};
try { g72 = $('Get Bot Session').first().json || {}; } catch (e) { g72 = {}; }
s.submission_key = String(g72.submission_key == null ? '' : g72.submission_key).trim();
const COLS = ['session_id','chat_id','user_id','username','first_name','last_name','language','state','created_at','updated_at','last_message_at','entry_source','selected_service','business_model','turnover_range','main_pain','urgency','has_cfo','documents_status','contact_phone','contact_email','contact_name','company','free_text_request','consent','lead_id','lead_sent_at','status','notes','raw_json','cycle_id','consent_cycle_id','consent_at','lead_cycle_id','lead_intake_ok','previous_lead_id','submission_key'];
const row = {};
for (const c of COLS) row[c] = (s[c] === undefined || s[c] === null) ? '' : String(s[c]).slice(0, 45000);
return [{ json: row }];

// Client confirmation message. Reached both after a fresh Intake call and on a retry where the lead already exists.
function safeText(v) { return String(v ?? '').replace(/\r/g, '').replace(/[<>]/g, '').replace(/[_*\[\]()~>#=|{}]/g, ' ').replace(/[ \t]{2,}/g, ' ').trim(); }
const b = $('Build Bot Response').first().json;
const p = $('Parse Telegram Update').first().json;
const cfg = (() => { try { return $('Settings to Object').first().json.settings || {}; } catch (e) { return {}; } })();
const site = cfg.website_url || 'https://finmentor.md';
let intake = null;
try { intake = $('Parse Intake Response').first().json; } catch (e) { intake = null; }
const persisted = $('Get Bot Session').first().json || {};
const ok = intake ? intake.intake_ok === true : String(persisted.lead_id || '') !== '';
const successText = 'Спасибо. Я передал ваш запрос эксперту FINMENTOR.\n\n' + 'Мы посмотрим контекст и вернёмся с подходящим первым шагом: Financial X-Ray, встреча или список данных для первичного анализа.\n\n' + 'Ничего дополнительно делать сейчас не нужно.';
const failText = 'Спасибо. Я зафиксировал ваш запрос.\n\n' + 'Мы проверим детали и вернёмся к вам в этом чате или по указанному контакту.';
const successRows = [
  [{ text: '📊 Что подготовить к разбору', callback_data: 'm|xray' }],
  [{ text: '💼 Услуги FINMENTOR', callback_data: 'm|services' }],
  [{ text: '🌐 Открыть сайт', url: site }],
  [{ text: '🏠 Главное меню', callback_data: 'n|menu' }]
];
const failRows = [
  [{ text: '🏠 Главное меню', callback_data: 'n|menu' }],
  [{ text: '🌐 Открыть сайт', url: site }]
];
const corr = (p.is_callback ? ('cb:' + String(p.callback_query_id || '')) : ('msg:' + String(p.chat_id || ''))) + ':confirm';
return [{ json: {
  chat_id: String(b.chat_id || p.chat_id || ''),
  text: safeText(ok ? successText : failText),
  keyboard_layout_id: ok ? 'L4_CCUC' : 'L2_CU',
  keyboard_data: { rows: ok ? successRows : failRows },
  parse_mode: '',
  disable_preview: true,
  correlation_id: corr.slice(0, 100),
  intake_ok: ok
} }];

// Records only whether the confirmation reached the client. lead_id / lead_intake_ok / cycle stamps were already
// persisted earlier and must never be lost because a confirmation send failed.
const t = $input.first().json || {};
const delivered = t.ok === true;
const p = $('Parse Telegram Update').first().json;
let base = {};
try { base = $('Parse Intake Response').first().json.session || {}; } catch (e) { base = $('Get Bot Session').first().json || {}; }
function note(s, flag) { const parts = String(s || '').split(';').map(x => x.trim()).filter(Boolean); if (!parts.includes(flag)) parts.push(flag); return parts.join('; ').slice(0, 500); }
const s = Object.assign({}, base);
s.chat_id = String(s.chat_id || p.chat_id || '');
s.updated_at = new Date().toISOString();
s.notes = note(s.notes, delivered ? 'confirmation_delivered' : 'confirmation_failed');
// P7.2 — `base` may come from Parse Intake Response, which does not carry the key.
// Re-attached FROM THE CYCLE GATE, exactly like the cycle fields, and for the same reason: the
// value is decided in one place and every writer reads it from there.
let g72 = {};
try { g72 = $('Get Bot Session').first().json || {}; } catch (e) { g72 = {}; }
s.submission_key = String(g72.submission_key == null ? '' : g72.submission_key).trim();
const COLS = ['session_id','chat_id','user_id','username','first_name','last_name','language','state','created_at','updated_at','last_message_at','entry_source','selected_service','business_model','turnover_range','main_pain','urgency','has_cfo','documents_status','contact_phone','contact_email','contact_name','company','free_text_request','consent','lead_id','lead_sent_at','status','notes','raw_json','cycle_id','consent_cycle_id','consent_at','lead_cycle_id','lead_intake_ok','previous_lead_id','submission_key'];
const row = {};
for (const c of COLS) row[c] = (s[c] === undefined || s[c] === null) ? '' : String(s[c]).slice(0, 45000);
return [{ json: row }];

// Controlled recovery: the business response could NOT be rendered, so we send a known-good
// static L1_C screen that returns the client to a safe, known point. The session is not advanced.
const t = $('Build Transport Request').first().json;
return [{ json: {
  chat_id: String(t.chat_id || ''),
  text: 'Не удалось корректно отобразить этот шаг. Вернитесь в главное меню и попробуйте ещё раз.',
  keyboard_layout_id: 'L1_C',
  keyboard_data: { rows: [[{ text: '🏠 Главное меню', callback_data: 'n|menu' }]] },
  parse_mode: '',
  disable_preview: true,
  correlation_id: (String(t.correlation_id || '') + ':recovery').slice(0, 100)
} }];

// Makes the presentation regression visible instead of hiding it.
// original_delivery_ok is always false here, regardless of whether the recovery message got through.
const t = $('Build Transport Request').first().json;
const b = $('Build Bot Response').first().json;
const p = $('Parse Telegram Update').first().json;
const d = b.debug || {};
const r = $input.first().json || {};
const recoveryOk = r.ok === true;
return [{ json: {
  event_id: `${p.chat_id}-unmapped-${Date.now()}`,
  ts: new Date().toISOString(),
  chat_id: String(p.chat_id || ''),
  user_id: String(p.user_id || ''),
  username: String(p.username || ''),
  event_type: 'presentation_layout_unmapped',
  state_before: String(d.state_before || ''),
  state_after: String(d.state_before || ''),
  message_text: String(p.message_text || '').slice(0, 500),
  callback_data: String(p.callback_data || ''),
  detail: `screen_state=${d.state_after || ''}; signature=${t.keyboard_signature || ''}; original_delivery_ok=false; recovery_delivery_ok=${recoveryOk}`,
  raw_json: JSON.stringify({ correlation_id: t.correlation_id || '', keyboard_signature: t.keyboard_signature || '', proposed_state_discarded: d.state_after || '', recovery: { ok: recoveryOk, error_code: r.error_code || '' } }).slice(0, 4000)
} }];

// Get Bot Session — the live cycle-semantics gate with explicit /start reset and the
// journey-origin locale added.
//
// GENERATED by scripts/build-premium-concierge.mjs from the live Get Bot Session node.
// DO NOT EDIT IN THE n8n UI: the next build overwrites it, and an edit here would not be
// covered by qa/ro-first-contact.test.mjs.
//
// PRESERVED:  the /start reset; EXTENDED: Telegram deep-link payload variants.
// ADDED:    the journey-origin locale capture (P1-01), lifted from
//           n8n/src/premium-ux/locale.js.
//
// /start archives the current lead reference, clears current-cycle state and mints a new
// cycle/submission key while durable historical lead/client facts remain intact.
//
// isRestart and hasNoCycle are UNCHANGED: a session with no cycle still bootstraps one, and
// the legacy m|diag restart stays as it is.
// CYCLE SEMANTICS GATE (P0 fix for stale consent).
// Every consumer that reads $('Get Bot Session') now sees a CYCLE-VALID view of the session:
// consent and lead_id from a previous application cycle are invalidated before the state machine ever sees them.
// A new cycle is created ONLY on an explicit reset: /start, or "Начать заново" (m|diag pressed on a session that
// already carries a consent decision, a lead, or an ended session). Plain navigation (/menu, n|menu) never changes it.
// An unfinished diagnostic cycle is never reset by m|diag, because there the same callback means "continue".
const p = $('Parse Telegram Update').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && String(r.chat_id == null ? '' : r.chat_id).trim() !== '');
